### Instruction:
Create a C program that prints out the Fibonacci sequence.

### Response:
#include <stdio.h>

int main()
{
    int i, num, first=0, second=1, next;
    printf("Enter the number of elements: ");
    scanf("%d", &num);
    printf("Fibonacci Series: ");
    for (i = 0; i < num; i++)
    {
        if (i <= 1)
            next = i;
        else
        {
            next = first + second;
            first = second;
            second = next;
        }
        printf("%d ", next);
    }
    return 0;
}

