### Input:
Array: [2, 8, 5, 3, 9]

### Response:
function SelectionSort(arr) {
  for (let i = 0; i < arr.length; i++) {
    let min = i;
    for (let j = i+1; j < arr.length; j++) {
      if (arr[j] < arr[min])
        min = j;
    }
    let temp = arr[i];
    arr[i] = arr[min];
    arr[min] = temp;
  } 
  return arr;
}

