using namespace std;

void minMax(int arr[], int n, int *min, int *max)
{
	*min = arr[0];  // Initialize minimum element
	*max = arr[0];  // Initialize maximum element

	for (int i = 1; i < n; i++)
	{
		if (arr[i] > *max)
			*max = arr[i];

		if (arr[i] < *min)
			*min = arr[i];
	}
}

